INSERT INTO "equations" VALUES('EQ01','Time-Space fibration','S2 -> T5 --pi--> S3','S^2\to T_5\xrightarrow{\pi}S^3','SOURCE_BACKED');
INSERT INTO "equations" VALUES('EQ02','Local fiber','Sigma_p = pi^(-1)(p) ~= S2','\Sigma_p:=\pi^{-1}(p)\cong S^2','SOURCE_BACKED');
INSERT INTO "equations" VALUES('EQ03','Corridor pullback','W_gamma = gamma^*(T5)','W_\gamma:=\gamma^*(T_5)','SOURCE_BACKED');
INSERT INTO "equations" VALUES('EQ04','Address','A_p=(p,Sigma_p,F_p,chi_p,Inv_p,R_p,B_p,O_p,H_p)','A_p=(p,\Sigma_p,F_p,\chi_p,\mathrm{Inv}_p,R_p,B_p,O_p,H_p)','NEW_DERIVATION');
INSERT INTO "equations" VALUES('EQ05','Rainbow Road','R = P_n o ... o P_1','\mathfrak R=\mathsf P_n\circ\cdots\circ\mathsf P_1','NEW_DERIVATION');
INSERT INTO "equations" VALUES('EQ06','Road transport','P_Gamma = P_n o ... o P_1','P_\Gamma=P_n\circ\cdots\circ P_1','NEW_DERIVATION');
INSERT INTO "equations" VALUES('EQ07','QFT naturality','rho_Q,beta o P_Gamma = U_Q(Gamma) o rho_Q,alpha','\rho_{Q,\beta}\circ P_\Gamma=U_Q(\Gamma)\circ\rho_{Q,\alpha}','FORMAL_TARGET');
INSERT INTO "equations" VALUES('EQ08','GR naturality','rho_G,beta o P_Gamma = U_G(Gamma) o rho_G,alpha','\rho_{G,\beta}\circ P_\Gamma=U_G(\Gamma)\circ\rho_{G,\alpha}','FORMAL_TARGET');
INSERT INTO "equations" VALUES('EQ09','Road-wise naturality theorem','local commuting squares => composite commuting square','(\forall i\;\rho_iP_i=U_i\rho_{i-1})\Rightarrow \rho_n(P_n\cdots P_1)=(U_n\cdots U_1)\rho_0','PROVED_FORMAL');
