INSERT INTO "theorems" VALUES('TR1','Portal Composition Identity Preservation','PROVED_FORMAL','Segmentwise persistent identity, chirality transport, and invariant-residue preservation survive composable Portal composition.');
INSERT INTO "theorems" VALUES('TR2','Projection Does Not Erase Formal Route Multiplicity','PROVED_FORMAL','For non-injective readout, equal readable endpoints need not imply equal full states or equal Road Histories.');
INSERT INTO "theorems" VALUES('TR3','Segmentwise Naturality Implies Road-wise Naturality','PROVED_FORMAL','If each Portal segment commutes with a sector representation and induced transport, the complete Rainbow Road commutes.');
INSERT INTO "theorems" VALUES('TR3A','Transport-Stable QFT/GR Common Ancestry','PROVED_FORMAL_CONDITIONAL','If QFT and GR naturality hold along the Road, their transported readable states retain common transported ancestry.');
